--
-- Name: data_entries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.data_entries AS
 SELECT dp.id,
    dp.submission_id,
    s.entity_id,
    s.period_id,
    m.id AS metric_id,
    dp.metric_code,
    dp.value_numeric,
    dp.value_text,
    dp.unit,
    dp.status,
    dp.created_at,
    dp.updated_at,
    dp.is_deleted
   FROM ((public.data_points dp
     JOIN public.submissions s ON ((s.id = dp.submission_id)))
     LEFT JOIN public.metrics m ON (((m.code)::text = (dp.metric_code)::text)));


